def parse_calls(s):
    calls=[]
    for m in re.finditer(r'<function=([^>]+)>(.*?)</function>', s, re.S):
        name=m.group(1); body=m.group(2)
        args={}
        for pm in re.finditer(r'<parameter=([^>]+)>\n?(.*?)\n?</parameter>', body, re.S):
            args[pm.group(1)]=pm.group(2).strip()
        calls.append((name,args))
    return calls
def norm_val(v):
